/* nussinov.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "nussinov.h"

/* RNA bases represented as chars, range is [0,3] */
typedef char base;

#define match(b1, b2) (((b1)+(b2)) == 3 ? 1 : 0)
#define max_score(s1, s2) ((s1 >= s2) ? s1 : s2)

/* Array initialization. */
static
void init_array (int n,
                 base POLYBENCH_1D(seq,N,n),
		 DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  int i, j;

  //base is AGCT/0..3
  for (i=0; i <n; i++) {
     seq[i] = (base)((i+1)%4);
  }

  for (i=0; i <n; i++)
     for (j=0; j <n; j++)
       table[i][j] = 0;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(table,N,N,n,n))

{
  int i, j;
  int t = 0;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("table");
  for (i = 0; i < n; i++) {
    for (j = i; j < n; j++) {
      if (t % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, table[i][j]);
      t++;
    }
  }
  POLYBENCH_DUMP_END("table");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/*
  Original version by Dave Wonnacott at Haverford College <davew@cs.haverford.edu>,
  with help from Allison Lake, Ting Zhou, and Tian Jin,
  based on algorithm by Nussinov, described in Allison Lake's senior thesis.

  Optimized version:
  - Reformulated the DP to iterate by increasing subsequence length L = j - i.
    For a given (i,j), all dependencies are on entries with smaller L, so
    all cells on the same diagonal (same L) are independent and can be
    computed in parallel.
  - Introduced OpenMP parallelization over each diagonal. This exploits
    the available 32 cores while preserving the exact dependence structure.
    When compiled without -fopenmp, the pragmas are ignored and the code
    remains correct and sequential.
  - Used local variables and explicit max logic to keep intermediate
    results in registers and reduce memory traffic.
  - Removed redundant bound checks that were implied by loop ranges.
  - Kept the mathematical recurrence identical to the original code, so
    the numeric results are unchanged.
*/
static
void kernel_nussinov[[gnu::flatten, gnu::noinline]](int n,
    base POLYBENCH_1D(seq,N,n),
    DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  /* Create local restrict-qualified aliases to help the compiler
     with alias analysis and enable better vectorization. */
  base *restrict seq_ = seq;
  DATA_TYPE (*restrict table_)[n] = table;

  const int N_ = n;

#pragma scop
  /* Dynamic programming over increasing subsequence length L = j - i.
     For fixed L, each (i,j=i+L) only depends on entries with smaller
     subsequence length, hence all cells on the same diagonal are
     independent and safely parallelizable. */
  #pragma omp parallel
  {
    for (int L = 1; L < N_; ++L) {
      /* Work-share the current diagonal across threads.
         Implicit barrier at the end of the 'for' ensures that all
         cells for subsequence length L are computed before any thread
         proceeds to L+1, which preserves the DP dependencies. */
      #pragma omp for schedule(static)
      for (int i = 0; i < N_ - L; ++i) {
        const int j = i + L;

        /* Start from the “left” option: table[i][j-1].
           In the original code, table[i][j] was initialized to 0 and then
           updated with max(table[i][j], table[i][j-1]) etc. Because all
           table[*][*] remain non-negative and initial values are 0, this
           is equivalent to starting with best = table[i][j-1]. */
        DATA_TYPE best = table_[i][j - 1];

        /* Option 2: skip base i (move down). */
        DATA_TYPE tmp = table_[i + 1][j];
        if (tmp > best)
          best = tmp;

        /* Option 3: pair i and j (if allowed) or just propagate
           table[i+1][j-1] if they are adjacent or don't match.

           Original logic:
             if (i < j-1)
               cand = table[i+1][j-1] + match(seq[i], seq[j]);
             else
               cand = table[i+1][j-1];

           We fold this into a single expression by using a 0/1 flag
           'can_pair'. For j == i+1, (i < j-1) is false, so can_pair = 0
           and we recover cand = table[i+1][j-1]. */
        const DATA_TYPE t2 = table_[i + 1][j - 1];
        const int can_pair = (i < j - 1) & match(seq_[i], seq_[j]);
        tmp = t2 + can_pair;
        if (tmp > best)
          best = tmp;

        /* Option 4: bifurcation: split at k, i < k < j. */
        for (int k = i + 1; k < j; ++k) {
          tmp = table_[i][k] + table_[k + 1][j];
          if (tmp > best)
            best = tmp;
        }

        table_[i][j] = best;
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(seq, base, N, n);
  POLYBENCH_2D_ARRAY_DECL(table, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_nussinov (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(table)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(seq);
  POLYBENCH_FREE_ARRAY(table);

  return 0;
}
