       table[i][j] = 0;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(table,N,N,n,n))

{
  int i, j;
  int t = 0;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("table");
  for (i = 0; i < n; i++) {
    for (j = i; j < n; j++) {
      if (t % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, table[i][j]);
      t++;
    }
  }
  POLYBENCH_DUMP_END("table");
  POLYBENCH_DUMP_FINISH;
}


/* --------------------------------------------------------------------
 * Optimized core DP update for a single cell (i,j).
 *
 * The DP state is stored in a flattened 1D view of the table:
 *   table[row * n + col] == original table[row][col]
 *
 * Semantics are identical to the original code:
 *   - Candidates:
 *       table[i][j-1]
 *       table[i+1][j]
 *       table[i+1][j-1] (+ match(seq[i], seq[j]) if j-i > 1)
 *       max over k in (i+1..j-1) of table[i][k] + table[k+1][j]
 *   - Initial value is the current table[i][j] (initialized to 0).
 *
 * Using a local accumulator (max_val) greatly reduces memory traffic
 * compared to repeatedly reading and writing table[i][j].
 * ------------------------------------------------------------------*/
static inline void
nussinov_update_cell(int n,
                     base *restrict seq,
                     DATA_TYPE *restrict table,
                     int i, int j)
{
  const int ij = i * n + j;

  /* Start from the current value in the table (initially 0). */
  DATA_TYPE max_val = table[ij];

  /* Candidate: table[i][j-1] */
  DATA_TYPE tmp = table[ij - 1];
  if (tmp > max_val)
    max_val = tmp;

  /* Candidate: table[i+1][j] */
  tmp = table[(i + 1) * n + j];
  if (tmp > max_val)
    max_val = tmp;

  /* Candidate: table[i+1][j-1] (+ possible base pair score).
     The original code forbids bonding adjacent bases, i.e., when j == i+1.
     That condition is equivalent to (j - i > 1) here. */
  tmp = table[(i + 1) * n + (j - 1)];
  if (j - i > 1) {
    tmp += (DATA_TYPE)match(seq[i], seq[j]);
  }
  if (tmp > max_val)
    max_val = tmp;

  /* Bifurcation candidates: max over k in [i+1, j-1]
     of table[i][k] + table[k+1][j]. */
  const int row_i = i * n;
  for (int k = i + 1; k < j; ++k) {
    DATA_TYPE cand = table[row_i + k]      /* table[i][k] */
                   + table[(k + 1) * n + j]; /* table[k+1][j] */
    if (cand > max_val)
      max_val = cand;
  }

  table[ij] = max_val;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/*
  Original version by Dave Wonnacott at Haverford College <davew@cs.haverford.edu>,
  with help from Allison Lake, Ting Zhou, and Tian Jin,
  based on algorithm by Nussinov, described in Allison Lake's senior thesis.

  Optimized version:

  - Processes the DP in increasing order of subsequence length (len = j - i).
    This respects all data dependencies while enabling parallelism.
  - Uses a flattened 1D view of the table to simplify addressing and
    improve compiler optimization of memory accesses.
  - Keeps a per-cell accumulator in a register to avoid repeated loads/stores
    of table[i][j].
  - Optionally exploits OpenMP parallelism over i for each fixed len.
*/
static void __attribute__((flatten, noinline))
kernel_nussinov(int n,
                base POLYBENCH_1D(seq,N,n),
		DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  /* Effective problem size used inside the SCoP; usually N == n. */
  const int N = _PB_N;

  base     *restrict seq_r   = seq;
  DATA_TYPE *restrict table1d = &table[0][0];

#if defined(_OPENMP)
  /* Parallel wavefront over increasing subsequence length.
     We create a single parallel region and distribute the work
     for each length across threads to avoid repeated team setup. */
  if (N >= OMP_NUSSINOV_MIN_N) {
    #pragma omp parallel
    {
      for (int len = 1; len < N; ++len) {
        #pragma omp for schedule(static)
        for (int i = 0; i < N - len; ++i) {
          int j = i + len;
          nussinov_update_cell(n, seq_r, table1d, i, j);
        }
      }
    }
    return;
  }
#endif

  /* Sequential version (also kept as a clean SCoP for polyhedral tools). */
#pragma scop
  for (int len = 1; len < N; ++len) {
    for (int i = 0; i < N - len; ++i) {
      int j = i + len;
      nussinov_update_cell(n, seq_r, table1d, i, j);
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(seq, base, N, n);
  POLYBENCH_2D_ARRAY_DECL(table, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_nussinov (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(table)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(seq);
  POLYBENCH_FREE_ARRAY(table);

  return 0;
}
