  based on algorithm by Nussinov, described in Allison Lake's senior thesis.
*/
static
void kernel_nussinov[[gnu::flatten, gnu::noinline]](int n,
                 base POLYBENCH_1D(seq,N,n),
                 DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  /* Create local restrict-qualified aliases to help the compiler
     with alias analysis and enable better optimization and
     potential vectorization. */
  base *restrict seq_local = seq;
  DATA_TYPE (*restrict table_local)[n] = table;

#pragma scop
  /* --------------------------------------------------------------------
   * Optimized dynamic-programming traversal
   *
   * Original code filled the DP table using:
   *   for (i = N-1; i >= 0; --i)
   *     for (j = i+1; j < N; ++j)
   *
   * Each table[i][j] depends only on entries corresponding to
   * strictly shorter subsequences:
   *   - table[i][j-1]      : length (j-1 - i)
   *   - table[i+1][j]      : length (j - (i+1))
   *   - table[i+1][j-1]    : length (j-1 - (i+1))
   *   - table[i][k]        : length (k - i),   i < k < j
   *   - table[k+1][j]      : length (j - (k+1)), i < k < j
   *
   * All these lengths are < (j - i), so we can legally reorder the
   * computation to process increasing subsequence length L = j - i.
   *
   * New traversal:
   *   for (L = 1; L < N; ++L)
   *     for (i = 0; i < N - L; ++i) {
   *       j = i + L;
   *       compute table[i][j];
   *     }
   *
   * This "wavefront" / diagonal traversal:
   *   - Preserves all original dependencies (topologically sorted).
   *   - Exposes parallelism across 'i' for fixed L (no loop-carried
   *     dependencies remain in that loop), which we exploit with
   *     OpenMP.
   *   - Allows us to keep a scalar accumulator 'best' in registers,
   *     significantly reducing memory traffic to table[i][j].
   * ------------------------------------------------------------------ */
  for (int len = 1; len < _PB_N; ++len) {
    int max_i = _PB_N - len;

    /* Parallelize computation along each diagonal.
       Every (i, j=i+len) is independent for a fixed 'len', because all
       dependencies go to smaller-length subsequences (handled in
       previous iterations of len).  The 'if' clause avoids creating
       parallel regions for very short diagonals.  If OpenMP is not
       enabled, this pragma is ignored and the code remains sequential. */
#pragma omp parallel for schedule(static) if (max_i > 32)
    for (int i = 0; i < max_i; ++i) {
      int j = i + len;

      /* Row pointers to improve locality and reduce address
         computation. */
      DATA_TYPE *restrict table_i   = table_local[i];
      DATA_TYPE *restrict table_ip1 = table_local[i + 1];

      /* Keep best score in a register.
         In this algorithm each (i,j) is written exactly once and the
         table is zero-initialized, so table_i[j] is 0 at this point.
         We still read it for semantic equivalence with the original
         code. */
      DATA_TYPE best = table_i[j];

      /* Option 1: j does not participate in a pair. */
      {
        DATA_TYPE cand = table_i[j - 1]; /* table[i][j-1] */
        if (cand > best)
          best = cand;
      }

      /* Option 2: i does not participate in a pair. */
      {
        DATA_TYPE cand = table_ip1[j]; /* table[i+1][j] */
        if (cand > best)
          best = cand;
      }

      /* Option 3: (i, j) pair together (if not adjacent),
         or just propagate table[i+1][j-1] in the adjacent case.

         This reproduces exactly the logic of the original code:

           if (j-1>=0 && i+1<_PB_N) {
             if (i<j-1)
               table[i][j] = max(table[i][j],
                                 table[i+1][j-1] + match(seq[i], seq[j]));
             else
               table[i][j] = max(table[i][j], table[i+1][j-1]);
           }

         Given len >= 1 in this loop, (j-1>=0 && i+1<_PB_N) always holds,
         so only the i < j-1 branch condition matters. */
      {
        DATA_TYPE base_val = table_ip1[j - 1]; /* table[i+1][j-1] */

        if (i < j - 1) {
          /* Non-adjacent: allow pairing with score match(seq[i], seq[j]). */
          DATA_TYPE cand =
              base_val + (DATA_TYPE)match(seq_local[i], seq_local[j]);
          if (cand > best)
            best = cand;
        } else {
          /* Adjacent: propagate table[i+1][j-1] without pairing. */
          if (base_val > best)
            best = base_val;
        }
      }

      /* Option 4: split at position k, combining two substructures.
         table[i][k] and table[k+1][j] are from strictly shorter
         subsequences, so they have already been computed in earlier
         'len' iterations. */
      for (int k = i + 1; k < j; ++k) {
        DATA_TYPE cand =
            table_i[k] + table_local[k + 1][j]; /* table[i][k] + table[k+1][j] */
        if (cand > best)
          best = cand;
      }

      /* Single write back to memory after all candidates considered. */
      table_i[j] = best;
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(seq, base, N, n);
  POLYBENCH_2D_ARRAY_DECL(table, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_nussinov (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(table)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(seq);
  POLYBENCH_FREE_ARRAY(table);

  return 0;
}
