}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/*
  Original version by Dave Wonnacott at Haverford College <davew@cs.haverford.edu>,
  with help from Allison Lake, Ting Zhou, and Tian Jin,
  based on algorithm by Nussinov, described in Allison Lake's senior thesis.
*/
static
void kernel_nussinov[[gnu::flatten, gnu::noinline]](int n, base POLYBENCH_1D(seq,N,n),
			   DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  /* Keep these for compatibility with PolyBench tooling; reused as indices. */
  int i, j, k;

  /* Local copy of the PolyBench problem size. */
  const int n_pb = _PB_N;

  /* Use restrict-qualified local pointers to help the optimizer.
     The PolyBench harness allocates seq and table as distinct objects. */
  base *restrict seq_ = seq;
  DATA_TYPE (*restrict table_)[n] = table;

#pragma scop
  /* Reorder the computation by increasing subsequence length ("wavefront"
     over diagonals).  All DP dependencies go from shorter to longer
     subsequences, so for a fixed length 'len' the (i,j) pairs with
     j-i == len are independent and can be parallelized. */
#pragma omp parallel private(i, j, k)
  {
    for (int len = 1; len < n_pb; ++len)
    {
      /* Parallel over starting index i for this fixed subsequence length.
         The implicit barrier at the end of 'omp for' ensures that all
         length-'len' entries are computed before any thread proceeds to
         length-'len-1', preserving the original dependencies. */
#pragma omp for schedule(static)
      for (i = 0; i < n_pb - len; ++i)
      {
        j = i + len;

        DATA_TYPE *row_i   = table_[i];
        DATA_TYPE *row_ip1 = table_[i + 1];

        /* Local accumulator for table[i][j].  Using a scalar greatly
           reduces memory traffic compared to repeatedly updating the
           table entry inside the inner k-loop. */
        DATA_TYPE best = row_i[j];

        /* Case 1: j is unpaired. */
        DATA_TYPE candidate = row_i[j - 1];
        if (candidate > best)
          best = candidate;

        /* Case 2: i is unpaired. */
        candidate = row_ip1[j];
        if (candidate > best)
          best = candidate;

        /* Case 3: i pairs with j, except for adjacent bases which are
           explicitly forbidden in the original code (i == j-1). */
        candidate = row_ip1[j - 1];
        if (i < j - 1)
        {
          const base si = seq_[i];
          const base sj = seq_[j];
          candidate += match(si, sj);
        }
        if (candidate > best)
          best = candidate;

        /* Case 4: bifurcation into two subintervals [i,k] and [k+1,j].
           This is purely a max-reduction; the OpenMP 'simd' reduction
           hint enables vectorization when OpenMP is enabled, while it
           is ignored by compilers that do not support OpenMP. */
#pragma omp simd reduction(max : best)
        for (k = i + 1; k < j; ++k)
        {
          DATA_TYPE cand = row_i[k] + table_[k + 1][j];
          if (cand > best)
            best = cand;
        }

        row_i[j] = best;
      } /* end for i */
    }   /* end for len */
  }     /* end parallel region */
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(seq, base, N, n);
  POLYBENCH_2D_ARRAY_DECL(table, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

